  KEY `assigned_by` (`assigned_by`),
  KEY `idx_tugas_user` (`user_id`),
  KEY `idx_tugas_assigned` (`assigned_by`),
  KEY `idx_tugas_status` (`status`),
  CONSTRAINT `tugas_lama_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `user` (`id`) ON DELETE CASCADE,
  CONSTRAINT `tugas_lama_ibfk_2` FOREIGN KEY (`assigned_by`) REFERENCES `user` (`id`) ON DELETE SET NULL
